import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";import{c as i,s as a}from"./chunks/assets.DeBnt35C.js";var o=JSON.parse(`{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"python/scrapy/index.md","filePath":"python/scrapy/index.md"}`),s={name:`python/scrapy/index.md`};function c(r,o,s,c,l,u){return n(),e(`div`,null,[...o[0]||=[t(`<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h1><ul><li>Scrapy 是一个快速高级的网络爬虫和网络抓取框架，用于爬取网站并从中提取结构化数据。它可用于广泛的用途，从数据挖掘到监控和自动化测试。</li><li>官方文档：<a href="https://docs.scrapy.net.cn/en/latest" target="_blank" rel="noreferrer">https://docs.scrapy.net.cn/en/latest</a></li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scrapy</span></span></code></pre></div><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to “工作流程”">​</a></h2><ol><li><p>一般情况 <img src="`+i+`" alt="" width="866" height="541"></p></li><li><p>scrapy 工作流程 <img src="`+a+`" alt="" width="550" height="388"></p></li></ol><h2 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to “组件”">​</a></h2><ul><li><strong>引擎(Engine)</strong>： <ul><li>总指挥：负责数据和信号在不同的模块之间的传递。</li><li>开发者基本不需要关注，由<code>scrapy</code>框架处理。</li></ul></li><li><strong>调度器(Scheduler)</strong>： <ul><li>一个队列，存放引擎发过来的请求。</li><li>开发者基本不需要关注，由<code>scrapy</code>框架处理。</li></ul></li><li><strong>下载器(Downloader)</strong>： <ul><li>下载吧引擎发过来的请求，下载完后，将响应发送给引擎。</li><li>开发者基本不需要关注，由<code>scrapy</code>框架处理。</li></ul></li><li><strong>爬虫(Spiders)</strong>： <ul><li>处理引擎发过来的 response，定义如何提取数据的规则, 进行数据提取。</li><li>开发者主要工作地方</li></ul></li><li><strong>项目管道(Pipeline)</strong>： <ul><li>负责处理提取到的数据，如存储到数据库或文件中。</li><li>开发者主要工作地方</li></ul></li><li><strong>中间件(Middlewares)</strong>： <ul><li>用于处理请求和响应，如添加 headers、处理 cookies 等。</li><li>开发者主要工作地方</li></ul></li></ul>`,8)]])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};